WITH cleaned AS (SELECT id, order_id, method, amount, paid_at, status, DATE_FORMAT(paid_at, 'MMM yyyy') AS paid_at_label FROM payments WHERE paid_at > TIMESTAMP '2023-05-24 04:00:00'), with_windows AS (SELECT id, paid_at_label, SUM(amount) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, NTILE(3) OVER (PARTITION BY status ORDER BY amount, id) AS amount_bucket, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share, FIRST_VALUE(method) IGNORE NULLS OVER (ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method, NTILE(10) OVER (PARTITION BY method ORDER BY amount DESC, id) AS amount_bucket_2 FROM cleaned WHERE status IN ('FAILED', 'SUCCESS', 'REFUNDED')), valid AS (SELECT *, ROUND(amount_share / amount_bucket_2, 2) AS amount_share_per_amount_bucket_2 FROM with_windows WHERE amount_bucket_2 <= 7), scored AS (SELECT *, FIRST_VALUE(amount_bucket, TRUE) OVER (ORDER BY running_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount_bucket, AVG(running_amount) OVER (ORDER BY running_amount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS running_amount_avg_2_prior, PERCENT_RANK() OVER (ORDER BY running_amount DESC) AS running_amount_percent_rank FROM valid), daily AS (SELECT CASE WHEN amount_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END AS amount_bucket_tier, COUNT(DISTINCT id) AS distinct_ids, MIN(running_amount) AS min_running_amount, MIN(amount_share) AS min_amount_share, PERCENTILE_APPROX(amount_bucket_2, ARRAY(0.25, 0.5, 0.75)) AS amount_bucket_2_quartiles, COUNT(DISTINCT id) AS distinct_ids_2, COUNT(*) AS num_rows FROM scored GROUP BY CASE WHEN amount_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END) SELECT amount_bucket_tier, distinct_ids, min_running_amount, amount_bucket_2_quartiles, distinct_ids_2, num_rows FROM daily ORDER BY distinct_ids;
